package com.dragonomous.dragopet;

/**
 * Every mood Drago can be in, with its sprite strip (32x32 frames side by side)
 * and how long each frame is shown.
 */
public enum DragoMood
{
	IDLE("idle.png", 350),
	LEVEL_UP("gz.png", 150),
	DEATH("cry.png", 150),
	DROP("purple.png", 120),
	LOW_HP("cope.png", 250),
	SLEEP("sleep.png", 250);

	private final String file;
	private final int frameMillis;

	DragoMood(String file, int frameMillis)
	{
		this.file = file;
		this.frameMillis = frameMillis;
	}

	public String getFile()
	{
		return file;
	}

	public int getFrameMillis()
	{
		return frameMillis;
	}
}

package com.dragonomous.dragopet;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(DragoPetConfig.GROUP)
public interface DragoPetConfig extends Config
{
	String GROUP = "dragopet";

	@Range(min = 1, max = 4)
	@ConfigItem(
		keyName = "size",
		name = "Size",
		description = "How big Drago is (1 = 32px, 2 = 64px, ...)",
		position = 0
	)
	default int size()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "speechBubbles",
		name = "Speech bubbles",
		description = "Let Drago say something when he reacts",
		position = 1
	)
	default boolean speechBubbles()
	{
		return true;
	}

	@ConfigItem(
		keyName = "levelUps",
		name = "Cheer on level-ups",
		description = "Drago parties when you gain a level",
		position = 2
	)
	default boolean levelUps()
	{
		return true;
	}

	@ConfigItem(
		keyName = "virtualLevels",
		name = "Virtual level-ups",
		description = "Also cheer for virtual levels past 99 (up to 126)",
		position = 3
	)
	default boolean virtualLevels()
	{
		return true;
	}

	@ConfigItem(
		keyName = "drops",
		name = "Celebrate drops",
		description = "Drago gets excited about valuable drops, new collection log slots and pets",
		position = 4
	)
	default boolean drops()
	{
		return true;
	}

	@ConfigItem(
		keyName = "deaths",
		name = "Cry on death",
		description = "Drago cries when you die",
		position = 5
	)
	default boolean deaths()
	{
		return true;
	}

	@ConfigItem(
		keyName = "lowHp",
		name = "Sweat on low HP",
		description = "Drago gets nervous when your hitpoints are low",
		position = 6
	)
	default boolean lowHp()
	{
		return true;
	}

	@Range(min = 1, max = 99)
	@ConfigItem(
		keyName = "lowHpPercent",
		name = "Low HP threshold (%)",
		description = "Below this percentage of your max hitpoints Drago starts sweating",
		position = 7
	)
	default int lowHpPercent()
	{
		return 25;
	}

	@ConfigItem(
		keyName = "sleep",
		name = "Fall asleep when idle",
		description = "Drago naps when you stand still for a minute",
		position = 8
	)
	default boolean sleep()
	{
		return true;
	}
}

package com.dragonomous.dragopet;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

class DragoPetOverlay extends Overlay
{
	private static final int FRAME = 32;
	private static final int BUBBLE_HEIGHT = 18;
	private static final int MIN_WIDTH = 96;
	private static final Color BUBBLE_FILL = new Color(255, 255, 255, 235);
	private static final Color BUBBLE_EDGE = new Color(20, 16, 22);

	private final DragoPetPlugin plugin;
	private final DragoPetConfig config;
	private final Map<DragoMood, BufferedImage[]> frames = new EnumMap<>(DragoMood.class);

	@Inject
	DragoPetOverlay(DragoPetPlugin plugin, DragoPetConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.BOTTOM_RIGHT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);

		for (DragoMood mood : DragoMood.values())
		{
			BufferedImage strip = ImageUtil.loadImageResource(DragoPetPlugin.class, mood.getFile());
			int count = Math.max(1, strip.getWidth() / FRAME);
			BufferedImage[] list = new BufferedImage[count];
			for (int i = 0; i < count; i++)
			{
				list[i] = strip.getSubimage(i * FRAME, 0, FRAME, FRAME);
			}
			frames.put(mood, list);
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		DragoMood mood = plugin.getMood();
		BufferedImage[] list = frames.get(mood);
		if (list == null)
		{
			return null;
		}

		int index = (int) ((System.currentTimeMillis() / mood.getFrameMillis()) % list.length);
		int size = FRAME * Math.max(1, Math.min(4, config.size()));
		boolean bubbles = config.speechBubbles();
		int width = bubbles ? Math.max(size, MIN_WIDTH) : size;
		int top = bubbles ? BUBBLE_HEIGHT : 0;

		String speech = plugin.getSpeech();
		if (bubbles && speech != null && !speech.isEmpty())
		{
			drawBubble(graphics, speech, width);
		}

		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		graphics.drawImage(list[index], (width - size) / 2, top, size, size, null);

		return new Dimension(width, top + size);
	}

	private void drawBubble(Graphics2D graphics, String text, int width)
	{
		Font font = FontManager.getRunescapeSmallFont();
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();
		int textWidth = metrics.stringWidth(text);
		int bubbleWidth = Math.min(width, textWidth + 10);
		int x = (width - bubbleWidth) / 2;
		int height = BUBBLE_HEIGHT - 4;

		graphics.setColor(BUBBLE_FILL);
		graphics.fillRoundRect(x, 0, bubbleWidth, height, 8, 8);
		graphics.setColor(BUBBLE_EDGE);
		graphics.setStroke(new BasicStroke(1));
		graphics.drawRoundRect(x, 0, bubbleWidth - 1, height - 1, 8, 8);

		// small tail pointing down at Drago
		int cx = width / 2;
		graphics.setColor(BUBBLE_FILL);
		graphics.fillPolygon(new int[]{cx - 3, cx + 3, cx}, new int[]{height - 1, height - 1, height + 3}, 3);
		graphics.setColor(BUBBLE_EDGE);
		graphics.drawLine(cx - 3, height - 1, cx, height + 3);
		graphics.drawLine(cx + 3, height - 1, cx, height + 3);

		int textY = (height - metrics.getHeight()) / 2 + metrics.getAscent();
		graphics.drawString(text, x + (bubbleWidth - textWidth) / 2, textY);
	}
}

package com.dragonomous.dragopet;

import com.google.inject.Provides;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Drago Pet",
	description = "A tiny pixel dragon companion that reacts to your level-ups, drops, deaths and low HP",
	tags = {"pet", "companion", "dragon", "fun", "overlay", "dragonomous"}
)
public class DragoPetPlugin extends Plugin
{
	/** Game ticks Drago stays in a reaction mood (1 tick = 0.6s). */
	private static final int LEVEL_UP_TICKS = 8;
	private static final int DROP_TICKS = 10;
	private static final int DEATH_TICKS = 10;
	/** Standing still this long (100 ticks = 60s) sends Drago to sleep. */
	private static final int SLEEP_AFTER_TICKS = 100;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private DragoPetOverlay overlay;

	@Inject
	private DragoPetConfig config;

	private final Map<Skill, Integer> knownLevels = new EnumMap<>(Skill.class);

	private DragoMood mood = DragoMood.IDLE;
	private String speech;
	private int reactionTicksLeft;
	private int stillTicks;
	private WorldPoint lastLocation;

	@Provides
	DragoPetConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DragoPetConfig.class);
	}

	@Override
	protected void startUp()
	{
		knownLevels.clear();
		setIdle();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		knownLevels.clear();
	}

	DragoMood getMood()
	{
		return mood;
	}

	String getSpeech()
	{
		return speech;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.LOGGING_IN)
		{
			// Levels are re-sent on login; forget them so that isn't mistaken for a level-up.
			knownLevels.clear();
			setIdle();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		// getLevel() stops at 99; the XP-based level keeps counting virtual levels up to 126.
		int level = Experience.getLevelForXp(event.getXp());
		Integer previous = knownLevels.put(skill, level);
		boolean virtual = level > Experience.MAX_REAL_LEVEL;
		if (previous != null && level > previous && config.levelUps() && (!virtual || config.virtualLevels()))
		{
			react(DragoMood.LEVEL_UP, LEVEL_UP_TICKS, "gz! " + skill.getName() + " " + level);
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (config.deaths() && event.getActor() == client.getLocalPlayer())
		{
			react(DragoMood.DEATH, DEATH_TICKS, "sit...");
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.drops())
		{
			return;
		}
		ChatMessageType type = event.getType();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		if (message.startsWith("You have a funny feeling like")
			|| message.startsWith("You feel something weird sneaking into your backpack"))
		{
			react(DragoMood.DROP, DROP_TICKS, "PET!!");
		}
		else if (message.startsWith("New item added to your collection log"))
		{
			react(DragoMood.DROP, DROP_TICKS, "new slot!");
		}
		else if (message.startsWith("Valuable drop"))
		{
			react(DragoMood.DROP, DROP_TICKS, "PURPLE?!");
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (reactionTicksLeft > 0)
		{
			reactionTicksLeft--;
			if (reactionTicksLeft == 0)
			{
				setIdle();
			}
			return;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}

		// Low HP has priority over idling and sleeping.
		if (config.lowHp() && isLowHp())
		{
			if (mood != DragoMood.LOW_HP)
			{
				mood = DragoMood.LOW_HP;
				speech = config.speechBubbles() ? "uh oh" : null;
			}
			stillTicks = 0;
			return;
		}
		if (mood == DragoMood.LOW_HP)
		{
			setIdle();
		}

		WorldPoint location = player.getWorldLocation();
		boolean standingStill = location != null && location.equals(lastLocation) && player.getAnimation() == -1;
		lastLocation = location;

		if (!standingStill)
		{
			stillTicks = 0;
			if (mood == DragoMood.SLEEP)
			{
				setIdle();
			}
			return;
		}

		stillTicks++;
		if (config.sleep() && stillTicks >= SLEEP_AFTER_TICKS && mood != DragoMood.SLEEP)
		{
			mood = DragoMood.SLEEP;
			speech = null;
		}
	}

	private boolean isLowHp()
	{
		int current = client.getBoostedSkillLevel(Skill.HITPOINTS);
		int max = client.getRealSkillLevel(Skill.HITPOINTS);
		return max > 0 && current > 0 && current * 100 < max * config.lowHpPercent();
	}

	private void react(DragoMood newMood, int ticks, String text)
	{
		mood = newMood;
		reactionTicksLeft = ticks;
		stillTicks = 0;
		speech = config.speechBubbles() ? text : null;
	}

	private void setIdle()
	{
		mood = DragoMood.IDLE;
		speech = null;
		reactionTicksLeft = 0;
		stillTicks = 0;
	}
}

package com.dragonomous.dragopet;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DragoPetPluginTest
